parameters.jsCode:
// Normalise an Evolution API v2 webhook into the Bonjee message schema.
// Returns { valid: false, reason } for anything we do not want to store.

const input = $input.first().json ?? {};
const root = input.body ?? input;

const rawEvent = root.event ?? root.type ?? '';
const event = String(rawEvent).toLowerCase();

// Evolution emits connection.update, qrcode.updated, presence.update, ...
if (!event.includes('messages.upsert') && !event.includes('messages_upsert')) {
  return [{ json: { valid: false, reason: 'ignored_event:' + (rawEvent || 'unknown') } }];
}

const data = root.data ?? {};
const key = data.key ?? {};

const externalId = key.id ?? data.id ?? '';
const remoteJid = key.remoteJid ?? data.remoteJid ?? '';
const fromMe = key.fromMe === true || data.fromMe === true;
const isGroup = String(remoteJid).endsWith('@g.us');
const senderId = key.participant ?? data.participant ?? remoteJid;

if (!externalId || !remoteJid) {
  return [{ json: { valid: false, reason: 'missing_id_or_chat' } }];
}

// Revoked / deleted messages arrive as protocolMessage with no content.
const message = data.message ?? {};
if (message.protocolMessage || message.senderKeyDistributionMessage) {
  return [{ json: { valid: false, reason: 'protocol_message', external_id: externalId } }];
}

function textOf(m) {
  if (!m || typeof m !== 'object') return '';
  return (
    m.conversation ??
    m.extendedTextMessage?.text ??
    m.imageMessage?.caption ??
    m.videoMessage?.caption ??
    m.documentMessage?.caption ??
    m.documentMessage?.fileName ??
    m.audioMessage?.caption ??
    m.buttonsResponseMessage?.selectedDisplayText ??
    m.listResponseMessage?.title ??
    m.templateButtonReplyMessage?.selectedDisplayText ??
    m.contactMessage?.displayName ??
    m.locationMessage?.name ??
    ''
  );
}

function typeOf(m) {
  if (!m || typeof m !== 'object') return 'unknown';
  if (m.conversation || m.extendedTextMessage) return 'text';
  if (m.imageMessage) return 'image';
  if (m.videoMessage) return 'video';
  if (m.audioMessage) return 'audio';
  if (m.documentMessage) return 'document';
  if (m.stickerMessage) return 'sticker';
  if (m.locationMessage) return 'location';
  if (m.contactMessage) return 'contact';
  return 'other';
}

const messageType = typeOf(message);
const content = String(textOf(message) || '');

// Nothing textual and no media reference: nothing useful to store.
if (!content && ['unknown', 'other'].includes(messageType)) {
  return [{ json: { valid: false, reason: 'empty_message', external_id: externalId } }];
}

const tsRaw = data.messageTimestamp ?? data.timestamp ?? Date.now();
let tsMs;
if (typeof tsRaw === 'number' || /^\d+$/.test(String(tsRaw))) {
  const n = Number(tsRaw);
  tsMs = n < 1e12 ? n * 1000 : n;
} else {
  tsMs = Date.parse(String(tsRaw));
  if (Number.isNaN(tsMs)) tsMs = Date.now();
}

const chatName = isGroup
  ? (data.groupName ?? String(remoteJid).split('@')[0])
  : (data.pushName ?? String(remoteJid).split('@')[0]);

return [{
  json: {
    valid: true,
    external_id: String(externalId),
    source: 'whatsapp',
    chat_id: String(remoteJid),
    chat_name: String(chatName),
    is_group: isGroup,
    sender_id: String(senderId),
    sender_name: String(data.pushName ?? ''),
    message_type: messageType,
    content: content,
    has_media: ['image', 'video', 'audio', 'document', 'sticker'].includes(messageType),
    mentioned_me: content.includes('@') || /\b(me|you)\b/i.test(content),
    from_me: fromMe,
    timestamp: new Date(tsMs).toISOString(),
    instance: String(root.instance ?? data.instance ?? ''),
    raw_payload: root
  }
}];

// Normalise a notification posted by the Bonjee Notifier Android app.
const input = $input.first().json ?? {};

// The app posts a JSON object directly; n8n may also nest it under body.
let data = input.body ?? input;
if (typeof data === 'string') {
  try { data = JSON.parse(data); } catch (e) { data = input; }
}

const appPackage = String(data.app_package ?? '').trim();
if (!appPackage) {
  return [{ json: { valid: false, reason: 'missing_app_package' } }];
}

const externalId = String(
  data.external_id ??
  `${appPackage}_${data.post_time ?? Date.now()}_${data.id ?? ''}`
);

const postTimeRaw = data.post_time ?? data.device_time ?? Date.now();
let postTimeMs;
if (typeof postTimeRaw === 'number' || /^\d+$/.test(String(postTimeRaw))) {
  const n = Number(postTimeRaw);
  postTimeMs = n < 1e12 ? n * 1000 : n;
} else {
  postTimeMs = Date.parse(String(postTimeRaw));
  if (Number.isNaN(postTimeMs)) postTimeMs = Date.now();
}

const content = String(
  data.content ?? data.big_text ?? data.text ?? data.ticker ?? ''
);

return [{
  json: {
    valid: true,
    external_id: externalId,
    app_package: appPackage,
    app_name: String(data.app_name ?? appPackage),
    title: String(data.title ?? ''),
    content: content,
    ticker: String(data.ticker ?? ''),
    post_time: new Date(postTimeMs).toISOString(),
    is_clearable: data.is_clearable !== false,
    category: String(data.category ?? ''),
    raw_payload: data
  }
}];

// Validate the question and derive search terms.
const input = $input.first().json ?? {};
const body = input.body ?? input;

const question = String(body.question ?? body.q ?? body.query ?? '').trim();

if (!question) {
  return [{ json: { valid: false, reason: 'Question is required.' } }];
}
if (question.length > 4000) {
  return [{ json: { valid: false, reason: 'Question is longer than 4000 characters.' } }];
}

// Strip punctuation so plainto_tsquery gets useful lexemes.
const terms = question
  .replace(/[^\p{L}\p{N}\s]/gu, ' ')
  .split(/\s+/)
  .filter((w) => w.length > 2)
  .slice(0, 12)
  .join(' ');

return [{
  json: {
    valid: true,
    question: question,
    search_terms: terms || question
  }
}];

// Merge evidence from messages + notifications into a grounded, honest answer.
// No LLM is called: this is deterministic retrieval so it cannot hallucinate.

const question = $('Validate Question').first().json.question;

let messages = [];
try { messages = $('Search Messages').all().map((i) => i.json).filter((r) => r && r.content); } catch (e) { messages = []; }

let notifications = [];
try { notifications = $('Search Notifications').all().map((i) => i.json).filter((r) => r && (r.content || r.title)); } catch (e) { notifications = []; }

const evidence = [
  ...messages.map((m) => ({
    kind: 'message',
    source: m.chat_name || m.chat_id,
    sender: m.sender_name || '',
    timestamp: m.timestamp,
    text: m.content,
    id: m.id
  })),
  ...notifications.map((n) => ({
    kind: 'notification',
    source: n.app_name,
    sender: '',
    timestamp: n.timestamp,
    text: [n.title, n.content].filter(Boolean).join(' — '),
    id: n.id
  }))
].sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

const hasEvidence = evidence.length > 0;

return [{
  json: {
    ok: true,
    question: question,
    answer: hasEvidence
      ? `Found ${evidence.length} archived item(s) matching your question. See supporting_messages below.`
      : 'No archived message or notification matched this question. The assistant does not invent answers.',
    current_answer: hasEvidence ? 'See supporting_messages.' : 'No matching evidence in the archive.',
    supporting_messages: evidence.slice(0, 20),
    changes_and_history: [],
    uncertainty: hasEvidence
      ? 'Keyword/lexical match only. Dates and corrections are not inferred. Enable the AI branch for synthesis.'
      : 'Nothing matched. Try different words, or check that ingestion is running.',
    suggested_next_action: hasEvidence
      ? 'Open the referenced message to confirm before acting on it.'
      : 'Send a test message and confirm it appears in the messages table.',
    evidence_count: evidence.length
  }
}];

parameters.query:
SELECT NOW() AS server_time,
       (SELECT COUNT(*) FROM messages) AS message_count,
       (SELECT COUNT(*) FROM notifications) AS notification_count;

parameters.jsCode:
// Report honestly: healthy only when the database answered.
const row = $input.first()?.json ?? {};
const dbOk = Boolean(row.server_time) && !row.error;

return [{
  json: {
    ok: dbOk,
    status: dbOk ? 'healthy' : 'degraded',
    service: 'bonjee-bot',
    checked_at: new Date().toISOString(),
    database: dbOk ? 'reachable' : 'unreachable',
    server_time: row.server_time ?? null,
    message_count: row.message_count ?? null,
    notification_count: row.notification_count ?? null
  }
}];
